import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './CharacterManager.css';

const CharacterManager = () => {
    const navigate = useNavigate();
    const [searchTerm, setSearchTerm] = useState('');
    const [characters, setCharacters] = useState([]); // Now starts completely empty
    const [isCreating, setIsCreating] = useState(false); // Controls the modal visibility

    // State for the new character form
    const [newChar, setNewChar] = useState({
        name: '',
        species: '',
        charClass: '',
        level: 1,
        imageUrl: 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=100&q=80'
    });

    // 1. Get the VIP token from storage
    const token = localStorage.getItem('token') || sessionStorage.getItem('token');

    // 2. Fetch characters as soon as the page loads
    useEffect(() => {
        if (!token) {
            alert("Please login first!");
            navigate('/');
            return;
        }
        fetchCharacters();
    }, [navigate, token]);

    const fetchCharacters = async () => {
        try {
            const response = await fetch('http://localhost:5001/api/characters', {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            const data = await response.json();

            if (response.ok) {
                setCharacters(data); // Put the characters from MongoDB into our state
            } else {
                console.error("Failed to fetch characters:", data.message);
            }
        } catch (error) {
            console.error("Connection error:", error);
        }
    };

    // 3. Submit the new character to MongoDB
    const handleCreateCharacter = async (e) => {
        e.preventDefault();

        try {
            const response = await fetch('http://localhost:5001/api/characters', {
                method: 'POST',
                headers: { 
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}` 
                },
                body: JSON.stringify(newChar)
            });

            const data = await response.json();

            if (response.ok) {
                alert("Character created successfully!");
                setIsCreating(false); // Close the modal
                setNewChar({ name: '', species: '', charClass: '', level: 1, imageUrl: newChar.imageUrl }); // Reset form
                fetchCharacters(); // Refresh the list to show the new character
            } else {
                alert("Error: " + data.message);
            }
        } catch (error) {
            console.error("Creation error:", error);
            alert("Failed to connect to the server.");
        }
    };

    const maxSlots = 6;
    const usedSlots = characters.length;

    return (
        <div className="manager-bg">
            <div className="manager-wrapper">

                {/* Header Section */}
                <div className="manager-header">
                    <div className="header-left">
                        <h1>My Characters</h1>
                        <p className="slots-info">Slots: <span className="highlight">{usedSlots}/{maxSlots} Used</span></p>
                    </div>
                    <div className="header-right">
                        <button 
                            className="create-btn" 
                            onClick={() => setIsCreating(true)}
                            disabled={usedSlots >= maxSlots} // Disable if slots are full
                        >
                            CREATE A CHARACTER
                        </button>
                        <a href="#" className="download-link">↓ Download a blank character sheet</a>
                    </div>
                </div>

                {/* Toolbar Section */}
                <div className="manager-toolbar">
                    <div className="search-box">
                        <input 
                            type="text" 
                            placeholder="🔍 Search by Name, Level, Class, Species..." 
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                    <div className="sort-box">
                        <select>
                            <option value="oldest">Created: Oldest</option>
                            <option value="newest">Created: Newest</option>
                            <option value="level">Level: High to Low</option>
                        </select>
                        <button className="settings-btn">⚙️ Settings</button>
                    </div>
                </div>

                {/* Character List Grid */}
                <div className="character-grid">
                    {characters.map(char => (
                        <div className="character-card" key={char._id}> {/* MongoDB uses _id */}
                            <div className="card-top">
                                <img src={char.imageUrl} alt={char.name} className="char-avatar" />
                                <div className="char-info">
                                    <h2>{char.name}</h2>
                                    <p>Level {char.level} | {char.species} | {char.charClass}</p>
                                </div>
                            </div>
                            <div className="card-actions">
                                <button className="action-btn">VIEW</button>
                                <button className="action-btn">EDIT</button>
                                <button className="action-btn">COPY</button>
                                <button className="action-btn delete-btn">DELETE</button>
                            </div>
                        </div>
                    ))}

                    {/* Empty State Message */}
                    {characters.length === 0 && (
                        <p style={{textAlign: 'center', width: '100%', color: '#bbb'}}>
                            Your adventure hasn't started yet. Create a character!
                        </p>
                    )}
                </div>

                {/* Back to Menu */}
                <div className="back-to-menu">
                    <button className="back-btn" onClick={() => navigate('/main-menu')}>
                        ← Back to Main Menu
                    </button>
                </div>

            </div>

            {/* CHARACTER CREATION MODAL */}
            {isCreating && (
                <div className="modal-overlay">
                    {/* We reuse the 'wrapper' class from your login form for that sweet glass effect! */}
                    <div className="modal-content wrapper">
                        <h2 style={{textAlign: 'center', marginBottom: '20px'}}>Forge Your Hero</h2>
                        <form onSubmit={handleCreateCharacter}>

                            <div className="input-box">
                                <input 
                                    type="text" 
                                    placeholder="Character Name" 
                                    required 
                                    value={newChar.name}
                                    onChange={(e) => setNewChar({...newChar, name: e.target.value})}
                                />
                            </div>

                            <div className="input-box">
                                <input 
                                    type="text" 
                                    placeholder="Species (e.g. Elf, Human)" 
                                    required 
                                    value={newChar.species}
                                    onChange={(e) => setNewChar({...newChar, species: e.target.value})}
                                />
                            </div>

                            <div className="input-box">
                                <input 
                                    type="text" 
                                    placeholder="Class (e.g. Wizard, Rogue)" 
                                    required 
                                    value={newChar.charClass}
                                    onChange={(e) => setNewChar({...newChar, charClass: e.target.value})}
                                />
                            </div>

                            <div className="input-box">
                                <input 
                                    type="number" 
                                    min="1" max="20"
                                    placeholder="Starting Level" 
                                    required 
                                    value={newChar.level}
                                    onChange={(e) => setNewChar({...newChar, level: e.target.value})}
                                />
                            </div>

                            <div className="modal-actions">
                                <button type="button" className="cancel-btn" onClick={() => setIsCreating(false)}>CANCEL</button>
                                <button type="submit" className="save-btn">CREATE</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default CharacterManager;
